import numpy as np


def effort(jt, a, o, P, F):
    return F @ a if jt == "prismatic" else np.cross(P - o, F) @ a

def double_integral_zoh(t_f, tau, t_query, t0):
    """J(t) = int_{t0}^{t} int_{t0}^{s} tau, exact for ZOH tau on the force grid."""
    k = max(int(np.searchsorted(t_f, t0, side="right")) - 1, 0)
