def q_sign_from_force(t, q, t_f, tau, t_stop):
    """+1/-1 such that, during the measured push, q moves the way the measured effort drives it.
    From any small initial velocity, q - q0 follows the double integral of tau while the push dominates;
    uses q and the applied force only. Returns the sign and the supporting correlation."""
    m = t <= t_stop
    J = double_integral_zoh(t_f, tau, t[m], t[0])
    dq = q[m] - q[m][0]
    num = float(dq @ J)
    r = float(np.corrcoef(dq, J)[0, 1]) if np.std(dq) > 0 and np.std(J) > 0 else 0.0
    return (1.0 if num >= 0 else -1.0), r, int(m.sum())
